src={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
tgt={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# source dimensions 9x10, target 10x9; transforms and translation
transforms={
'cw':lambda r,c:(c,8-r), 'ccw':lambda r,c:(9-c,r), 'transpose':lambda r,c:(c,r), 'anti':lambda r,c:(9-c,8-r),
'identity':lambda r,c:(r,c), 'rot180':lambda r,c:(8-r,9-c), 'flipv':lambda r,c:(8-r,c), 'fliph':lambda r,c:(r,9-c)}
for n,f in transforms.items():
  pts={f(r,c) for r,c in src}
  # align min coordinates to target min
  dy=min(r for r,c in tgt)-min(r for r,c in pts); dx=min(c for r,c in tgt)-min(c for r,c in pts)
  pts={(r+dy,c+dx) for r,c in pts}
  print(n, pts==tgt, len(pts&tgt))
